import CustomCheckbox from '@/components/CrmUi/Checkbox';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { CEDENTE_BANCO_OPTIONS, CEDENTE_ESTADO_CIVIL_OPTIONS, CEDENTE_ESTADO_OPTIONS, CEDENTE_NACIONALIDADE_DEFAULT } from '@/constants/cedentes';
import {
    AGENCIA_CLEAVE_OPTIONS,
    CEP_CLEAVE_OPTIONS,
    CHAVE_ALEATORIA_CLEAVE_OPTIONS,
    CONTA_CLEAVE_OPTIONS,
    CPF_CLEAVE_OPTIONS,
    DATA_CLEAVE_OPTIONS,
    TELEFONE_CLEAVE_OPTIONS,
} from '@/constants/cleave-options';
import { QueryKeys } from '@/constants/query-keys';
import { ProductCombobox, ProductSelect } from '@/design-system';
import { resolveOficioCedentePrefill } from '@/functions/broker/oficio-cedente-prefill';
import {
    buildCedentePfEnrichFillIfEmpty,
    countMissingCedentePfSoftFields,
    shouldSuggestCedentePfEnrich,
} from '@/functions/broker/cedente-pf-enrich-suggestion';
import {
    mapCedenteDataToFormValues,
    shouldHydrateCedenteForm,
} from '@/functions/broker/map-cedente-data-to-form-values';
import { handleCedenteFormValidationFailure, captureCedenteFormEvent } from '@/functions/analytics/cedenteFormValidationUx';
import { applyCedenteFullSchemaValidation } from '@/functions/broker/applyCedenteFullSchemaValidation';
import { CPFAndCNPJMask } from '@/functions/formaters/CPFAndCNPJInput';
import { validationSelectPix } from '@/functions/formaters/validationPix';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import { reverificarExigenciasProposta } from '@/functions/propostas/reverificar-exigencias-proposta';
import {
    useExtratoCedenteDataQuery,
    useOficioLinkedCedentesQuery,
} from '@/hooks/queries/cedentes';
import { useExtratoDataQueryOptions } from '@/hooks/queries/extrato';
import { usePFDataQuery } from '@/hooks/queries/use-direct-data';
import { createNewCedente, updateCedenteInfo } from '@/services/BrokerServices';
import { fetchAddressByCep } from '@/services/cep/fetchAddressByCep';
import { getPFData } from '@/services/direct-data';
import { CedenteEnrichSuggestionBanner } from './CedenteEnrichSuggestionBanner';
import { linkCedenteToExtratoWithAutoEsteira } from '@/services/oficios';
import { PixOption } from '@/types/pix';
import queryClient from '@/utils/queryClient';
import { zodResolver } from '@hookform/resolvers/zod';
import { useMutation, useQuery } from '@tanstack/react-query';
import { AxiosError } from 'axios';
import Cleave from 'cleave.js/react';
import {
    ArrowLeft,
    AtSign,
    BadgeAlert,
    BadgeCheck,
    Banknote,
    BriefcaseBusiness,
    Building,
    Building2,
    CalendarDays,
    CreditCard,
    Flag,
    Home,
    HousePlus,
    IdCard,
    Landmark,
    LoaderCircle,
    Map,
    MapPin,
    Mars,
    Percent,
    Phone,
    Search,
    TriangleAlert,
    University,
    User,
    Venus,
} from 'lucide-react';
import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Controller, FieldErrors, useForm } from 'react-hook-form';
import type { ICedenteRegistrationShellProps } from '../../../interfaces/cedenteRegistrationShell';
import { PixTypeSelect } from '../PixTypeSelect';
import {
    CEDENTE_FIELD_ERROR_CLASS,
    CEDENTE_FIELD_LABEL_CLASS,
    CEDENTE_FORM_GRID_CLASS,
    CEDENTE_FORM_SHELL_CLASS,
    CedenteFormActions,
    CedenteCepLookupStatus,
    CedenteFormBackButton,
    CedenteFormNotice,
    CedenteFormSection,
    CedenteFormSectionHeader,
    getCedenteFormInputClass,
} from './cedenteRegistrationFormUi';
import {
    PF_PARTIAL_CREATE_REQUIRED_FIELDS,
    buildCedenteCreateFormFields,
    pfCedenteFormSchema,
    pfCedentePartialSaveSchema,
    type PfCedenteFormValues,
} from './schemas/cedente-form-schemas';
import { useCedenteRegistrationDeps } from './utils/useCedenteRegistrationDeps';

const RegisterPFCedenteForm = ({
    isFromFormPj = false,
    closeModal,
    backStepForm,
    mode = 'create',
    closePfModalFromPj,
    readonly = false,
    registrationShell,
    onCreated,
}: {
    isFromFormPj?: boolean;
    mode?: 'create' | 'edit' | 'createFromPj';
    closeModal: () => void;
    closePfModalFromPj?: () => void;
    backStepForm?: () => void;
    cedenteId?: string;
    readonly?: boolean;
    registrationShell?: ICedenteRegistrationShellProps;
    onCreated?: (cedente: { id: string; nome: string }) => void;
}) => {
    const { extratoId, cessionPercentageAvailable, representanteLegalId } =
        useCedenteRegistrationDeps(registrationShell);
    const initialTipo = registrationShell?.initialTipo ?? 'PF';

    // ==================
    // # React Queries
    // ==================
    const { data: representanteData, isLoading: isLoadingRepresentanteData } =
        useExtratoCedenteDataQuery(representanteLegalId ?? '');
    const { data: extratoData } = useQuery(useExtratoDataQueryOptions(extratoId));
    const { data: linkedCedentesList, isSuccess: isLinkedCedentesLoaded } =
        useOficioLinkedCedentesQuery(extratoId);
    const vigenteProposalData = extratoData?.propostas?.find((p) => p.vigente);
    const hasLinkedCedente = (linkedCedentesList?.length ?? 0) > 0;

    // ==================
    // # Hook Form
    // ==================
    const {
        register,
        handleSubmit,
        control,
        setValue,
        setFocus,
        getValues,
        setError,
        clearErrors,
        watch,
        formState: { errors, dirtyFields },
    } = useForm<PfCedenteFormValues>({
        resolver: zodResolver(pfCedentePartialSaveSchema),
        shouldFocusError: false,
        // defaultValues (not `values`) — controlled `values` resets fields every render and breaks CPF/CEP autofill
        defaultValues: {
            nacionalidade: CEDENTE_NACIONALIDADE_DEFAULT,
            telefone: '',
            cep: '',
            cpf: '',
            data_nascimento: '',
            rg: '',
            bairro: '',
            municipio: '',
            estado: '',
            complemento: '',
            email: '',
            logradouro: '',
            nome: '',
            nome_mae: '',
            nome_pai: '',
            orgao_exp_rg: '',
            profissao: '',
            tipo: initialTipo,
            agencia: '',
            conta: '',
            pix: '',
            banco: '',
            percentual_cessao: '',
            estado_civil: '',
        },
    });

    const [pixOption, setPixOption] = useState<PixOption>('Telefone');
    const [isSearchingCep, setIsSearchingCep] = useState(false);
    const [isFullPercentage, setIsFullPercentage] = useState(() =>
        cessionPercentageAvailable === 100 ? true : false,
    );
    const [debouncedCpf, setDebouncedCpf] = useState('');
    const [oficioPrefillNotice, setOficioPrefillNotice] = useState<string | null>(null);
    const lastCepLookupDigitsRef = useRef<string | null>(null);
    const hydratedRepresentanteIdRef = useRef<string | null>(null);
    const didPrefillFromOficioRef = useRef(false);
    const nameLockedFromOficioRef = useRef(false);
    const [enrichSuggestionDismissed, setEnrichSuggestionDismissed] = useState(false);
    const [isEnrichingPf, setIsEnrichingPf] = useState(false);
    /** 'partial' = Salvar (soft); 'finalize' = Finalizar Cadastro (full). */
    const saveIntentRef = useRef<'partial' | 'finalize'>('partial');
    let createCedenteToastId: string | number | undefined;

    const currentCpf = watch('cpf') || '';

    const { data: pfData, isLoading: isLoadingPFData } = usePFDataQuery(
        mode === 'create' && debouncedCpf ? debouncedCpf : '',
    );

    // mutations
    const createCedente = useMutation({
        mutationFn: async (paramObj: { data: PfCedenteFormValues; formFields: string[] }) => {
            const { data, formFields } = paramObj;
            const req = await createNewCedente(data as any, formFields);
            return req;
        },
        onMutate: () => {
            const isPartial = saveIntentRef.current === 'partial';
            createCedenteToastId = sendToastMessage({
                title: isPartial ? 'Salvando dados...' : 'Cadastrando cedente...',
                description: 'Este processo pode levar alguns segundos.',
                type: 'loading',
            });
            captureCedenteFormEvent(
                isPartial
                    ? 'crm_broker_cedente_form_save_partial_started'
                    : 'crm_broker_cedente_form_finalize_started',
                { form_tipo: 'PF', mode: mode === 'edit' ? 'edit' : 'create' },
            );
        },
        onError: (error) => {
            if (error instanceof AxiosError) {
                captureCedenteFormEvent(
                    saveIntentRef.current === 'partial'
                        ? 'crm_broker_cedente_form_save_partial_failed'
                        : 'crm_broker_cedente_form_finalize_failed',
                    { form_tipo: 'PF', mode: mode === 'edit' ? 'edit' : 'create', reason: 'api' },
                );
                sendToastMessage({
                    title: error.response?.data.detail || 'Erro ao criar cadastro.',
                    type: 'error',
                    previousToastId: createCedenteToastId,
                });
            }
        },
        onSuccess: async (data, paramObj) => {
            const { data: formData } = paramObj;
            const isPartial = saveIntentRef.current === 'partial';
            captureCedenteFormEvent(
                isPartial
                    ? 'crm_broker_cedente_form_save_partial_succeeded'
                    : 'crm_broker_cedente_form_finalize_succeeded',
                { form_tipo: 'PF', mode: mode === 'edit' ? 'edit' : 'create' },

content.content:
400	        data: PfCedenteFormValues,
401	        event?: React.BaseSyntheticEvent,
402	        intent: 'partial' | 'finalize' = 'partial',
403	    ) => {
404	        event?.stopPropagation();
405	        saveIntentRef.current = intent;
406	
407	        let modifiedFormFields = buildCedenteCreateFormFields(
408	            data as unknown as Record<string, unknown>,
409	            dirtyFields,
410	            PF_PARTIAL_CREATE_REQUIRED_FIELDS,
411	        );
412	
413	        // Garante que 'tipo' sempre seja incluído
414	        if (!modifiedFormFields.includes('tipo')) {
415	            modifiedFormFields = [...modifiedFormFields, 'tipo'];
416	        }
417	
418	        // Garante que 'nacionalidade' sempre seja incluído quando preenchida
419	        if (data.nacionalidade && !modifiedFormFields.includes('nacionalidade')) {
420	            modifiedFormFields = [...modifiedFormFields, 'nacionalidade'];
421	        }
422	
423	        if (data.telefone) {
424	            data.telefone = data.telefone.replace(/\D/g, ''); // remove tudo que não for dígito
425	        }
426	
427	        if (data.data_nascimento) {
428	            data.data_nascimento = data.data_nascimento.split('/').reverse().join('-');
429	        }
430	
431	        if (data.numero) {
432	            data.numero = String(data.numero);
433	        }
434	
435	        if (mode === 'create' || mode === 'createFromPj') {
436	            await createCedente.mutateAsync({
437	                data,
438	                formFields: modifiedFormFields,
439	            });
440	            return;
441	        }
442	
443	        if (mode === 'edit' && modifiedFormFields.length > 0) {
444	            await updateCedente.mutateAsync({
445	                data,
446	                formFields: modifiedFormFields,
447	            });
448	        } else if (mode === 'edit') {
449	            sendToastMessage({
450	                title: 'Atenção',
451	                description: 'É necessário ao menos modificar um campo para atualizar os dados.',
452	                type: 'warning',
453	            });
454	        }
455	    };
456	
457	    function onFormFailure(formErrors: FieldErrors<PfCedenteFormValues>) {
458	        captureCedenteFormEvent('crm_broker_cedente_form_save_partial_failed', {
459	            form_tipo: 'PF',
460	            mode: mode === 'edit' ? 'edit' : 'create',
461	            reason: 'client_validation',
462	        });
463	        handleCedenteFormValidationFailure({
464	            errors: formErrors,
465	            formTipo: 'PF',
466	            mode: mode === 'edit' ? 'edit' : 'create',
467	            setFocus: (name) => setFocus(name as Parameters<typeof setFocus>[0]),
468	        });
469	    }
470	
471	    function onSavePartial(data: PfCedenteFormValues, event?: React.BaseSyntheticEvent) {
472	        return onSubmit(data, event, 'partial');
473	    }
474	
475	    async function onFinalizeClick() {
476	        const values = getValues();
477	        const isValid = applyCedenteFullSchemaValidation({
478	            schema: pfCedenteFormSchema,
479	            values,
480	            setError,
481	            clearErrors,
482	            formTipo: 'PF',
483	            mode: mode === 'edit' ? 'edit' : 'create',
484	            setFocus: (name) => setFocus(name as Parameters<typeof setFocus>[0]),
485	        });
486	        if (!isValid) return;
487	        await onSubmit(values, undefined, 'finalize');
488	    }
489	
490	    useEffect(() => {
491	        hydratedRepresentanteIdRef.current = null;
492	    }, [representanteLegalId]);
493	
494	    useEffect(() => {
495	        if (mode !== 'edit' || !representanteData) return;
496	        const incomingId = String(representanteData.id || representanteLegalId || '');
497	        if (!shouldHydrateCedenteForm(hydratedRepresentanteIdRef.current, incomingId)) return;
498	
499	        setPixOption(
500	            validationSelectPix(
501	                representanteData.informacoes_bancarias?.pix || '',
502	            ) as unknown as PixOption,
503	        );
504	        const mapped = mapCedenteDataToFormValues(representanteData, 'pf');
505	        for (const [key, value] of Object.entries(mapped)) {
506	            setValue(key as keyof PfCedenteFormValues, value);
507	        }
508	        hydratedRepresentanteIdRef.current = incomingId;
509	    }, [representanteData, mode, representanteLegalId, setValue]);
510	
511	    useEffect(() => {
512	        if (mode === 'create' && isFullPercentage && cessionPercentageAvailable > 0) {
513	            setValue('percentual_cessao', '100');
514	        }
515	    }, [mode, isFullPercentage, cessionPercentageAvailable, setValue]);
516	
517	    useEffect(() => {
518	        if (
519	            mode !== 'create' ||
520	            isFromFormPj ||
521	            didPrefillFromOficioRef.current ||
522	            !extratoData ||
523	            !isLinkedCedentesLoaded
524	        ) {
525	            return;
526	        }
527	
528	        const prefill = resolveOficioCedentePrefill({
529	            oficio: extratoData,
530	            hasLinkedCedente,
531	            formTipo: 'PF',
532	        });
533	        if (!prefill) return;
534	
535	        didPrefillFromOficioRef.current = true;
536	        nameLockedFromOficioRef.current = true;
537	        setValue('nome', prefill.name, { shouldDirty: true });
538	        setValue('cpf', prefill.documentMasked, { shouldDirty: true });
539	        setOficioPrefillNotice(prefill.reviewNotice);
540	    }, [
541	        mode,
542	        isFromFormPj,
543	        extratoData,
544	        hasLinkedCedente,
545	        isLinkedCedentesLoaded,
546	        setValue,
547	    ]);
548	
549	    useEffect(() => {
550	        if (mode === 'create' && pfData?.retorno) {
551	            const data = pfData.retorno;
552	
553	            // Ofício name wins over bureau; keep asking the user to review.
554	            if (data.nome && !nameLockedFromOficioRef.current) {
555	                setValue('nome', data.nome, { shouldDirty: true });
556	            }
557	            if (data.nomeMae) setValue('nome_mae', data.nomeMae, { shouldDirty: true });
558	            if (data.dataNascimento) {
559	                // Converte de YYYY-MM-DD para DD/MM/YYYY
560	                const dataFormatada = data.dataNascimento.split(' ')[0];
561	                setValue('data_nascimento', dataFormatada, { shouldDirty: true });
562	            }
563	
564	            const primeiroTelefone = data.telefones?.[0]?.telefoneComDDD;
565	            if (primeiroTelefone) setValue('telefone', primeiroTelefone, { shouldDirty: true });
566	
567	            const primeiroEmail = data.emails?.[0]?.enderecoEmail;
568	            if (primeiroEmail) setValue('email', primeiroEmail, { shouldDirty: true });
569	
570	            const endereco = data.enderecos?.[0];
571	            if (endereco) {
572	                if (endereco.cep) setValue('cep', endereco.cep, { shouldDirty: true });
573	                if (endereco.logradouro)
574	                    setValue('logradouro', endereco.logradouro, { shouldDirty: true });
575	                if (endereco.numero) setValue('numero', endereco.numero, { shouldDirty: true });
576	                if (endereco.complemento)
577	                    setValue('complemento', endereco.complemento, { shouldDirty: true });
578	                if (endereco.bairro) setValue('bairro', endereco.bairro, { shouldDirty: true });
579	                if (endereco.cidade) setValue('municipio', endereco.cidade, { shouldDirty: true });
580	                if (endereco.uf) setValue('estado', endereco.uf, { shouldDirty: true });
581	            }
582	        }
583	    }, [pfData, mode, setValue]);
584	
585	    useEffect(() => {
586	        const handler = setTimeout(() => {
587	            setDebouncedCpf(currentCpf);
588	        }, 700);
589	        return () => clearTimeout(handler);
590	    }, [currentCpf]);
591	
592	    useEffect(() => {
593	        setEnrichSuggestionDismissed(false);
594	    }, [debouncedCpf]);
595	
596	    const watchedSoftForEnrich = watch([
597	        'rg',
598	        'data_nascimento',
599	        'estado_civil',
600	        'profissao',
601	        'nome_mae',
602	        'nome_pai',
603	        'nacionalidade',
604	        'telefone',
605	        'email',
606	        'cep',
607	        'nome',
608	        'logradouro',
609	        'numero',
610	        'complemento',
611	        'bairro',
612	        'municipio',
613	        'estado',
614	    ]);
615	
616	    const pfEnrichFormValues = useMemo(
617	        () => ({
618	            cpf: currentCpf,
619	            rg: watchedSoftForEnrich[0],
620	            data_nascimento: watchedSoftForEnrich[1],
621	            estado_civil: watchedSoftForEnrich[2],
622	            profissao: watchedSoftForEnrich[3],
623	            nome_mae: watchedSoftForEnrich[4],
624	            nome_pai: watchedSoftForEnrich[5],
625	            nacionalidade: watchedSoftForEnrich[6],
626	            telefone: watchedSoftForEnrich[7],
627	            email: watchedSoftForEnrich[8],
628	            cep: watchedSoftForEnrich[9],
629	            nome: watchedSoftForEnrich[10],
630	            logradouro: watchedSoftForEnrich[11],
631	            numero: watchedSoftForEnrich[12],
632	            complemento: watchedSoftForEnrich[13],
633	            bairro: watchedSoftForEnrich[14],
634	            municipio: watchedSoftForEnrich[15],
635	            estado: watchedSoftForEnrich[16],
636	        }),
637	        [currentCpf, watchedSoftForEnrich],
638	    );
639	
640	    const pfMissingSoftCount = useMemo(
641	        () => countMissingCedentePfSoftFields(pfEnrichFormValues),
642	        [pfEnrichFormValues],
643	    );
644	
645	    const isCreateLikeMode = mode === 'create' || mode === 'createFromPj';
646	
647	    const showPfEnrichSuggestion =
648	        isCreateLikeMode &&
649	        !isLoadingPFData &&
650	        shouldSuggestCedentePfEnrich({
651	            cpf: currentCpf,
652	            values: pfEnrichFormValues,
653	            dismissed: enrichSuggestionDismissed,
654	            readonly,
655	        });
656	
657	    async function handleEnrichPfFromDirectData() {
658	        if (!currentCpf || isEnrichingPf) return;
659	        setIsEnrichingPf(true);
660	        try {
661	            const response = await getPFData(currentCpf);
662	            if (!response?.retorno) {
663	                sendToastMessage({
664	                    title: 'Não encontramos dados para este CPF.',
665	                    type: 'warning',
666	                });
667	                return;
668	            }
669	
670	            const current = {
671	                ...pfEnrichFormValues,
672	                ...getValues(),
673	            };
674	            const fill = buildCedentePfEnrichFillIfEmpty(current, response.retorno);
675	            const filledKeys = Object.keys(fill);
676	            if (filledKeys.length === 0) {
677	                sendToastMessage({
678	                    title: 'Nenhum campo vazio pôde ser preenchido com a consulta.',
679	                    type: 'info',
680	                });
681	                return;
682	            }
683	
684	            for (const [key, value] of Object.entries(fill)) {
685	                if (value == null) continue;
686	                // Ofício name always wins over bureau.
687	                if (key === 'nome' && nameLockedFromOficioRef.current) continue;
688	                setValue(key as keyof typeof fill, String(value), { shouldDirty: true });
689	            }
690	
691	            sendToastMessage({
692	                title: 'Ativos Intelligence preencheu os campos vazios. Revise antes de salvar.',
693	                type: 'success',
694	            });
695	        } catch (error) {
696	            const message =
697	                error instanceof Error && error.message
698	                    ? error.message
699	                    : 'Falha ao consultar dados do CPF.';
700	            sendToastMessage({ title: message, type: 'error' });
701	        } finally {
702	            setIsEnrichingPf(false);
703	        }
704	    }
705	
706	    if (mode === 'edit' && isLoadingRepresentanteData)
707	        return (
708	            <div className="flex min-h-50 items-center justify-center gap-3 font-satoshi">
709	                <LoaderCircle size={24} className="animate-spin text-accent" />
710	                <p className="text-sm text-muted-foreground">Buscando informações do cedente...</p>
711	            </div>
712	        );
713	
714	    return (
715	        <form
716	            onSubmit={handleSubmit(onSavePartial, onFormFailure)}
717	            className={CEDENTE_FORM_SHELL_CLASS}
718	        >
719	            {mode === 'create' && (backStepForm || (isFromFormPj && closePfModalFromPj)) && (
720	                <CedenteFormBackButton
721	                    icon={<ArrowLeft size={16} className="transition-transform group-hover:-translate-x-0.5" />}
722	                    onClick={() => {
723	                        if (isFromFormPj) {
724	                            closePfModalFromPj?.();
725	                        } else {
726	                            backStepForm?.();
727	                        }
728	                    }}
729	                />
730	            )}
731	
732	            {oficioPrefillNotice && (
733	                <CedenteFormNotice variant="warning" icon={TriangleAlert}>
734	                    {oficioPrefillNotice}
735	                </CedenteFormNotice>
736	            )}
737	
738	            {showPfEnrichSuggestion && (
739	                <CedenteEnrichSuggestionBanner
740	                    missingCount={pfMissingSoftCount}
741	                    isEnriching={isEnrichingPf}
742	                    onEnrich={() => {
743	                        void handleEnrichPfFromDirectData();
744	                    }}
745	                    onDismiss={() => setEnrichSuggestionDismissed(true)}
746	                />
747	            )}
748	
749	            <CedenteFormSection>
750	                <CedenteFormSectionHeader icon={User} title="Dados Pessoais" />
751	                <div className={CEDENTE_FORM_GRID_CLASS}>
752	                    {/* nome completo */}
753	                    <div className="relative col-span-1">
754	                        <label
755	                            htmlFor="nome_completo"
756	                            className={CEDENTE_FIELD_LABEL_CLASS}
757	                        >
758	                            <User size={18} />
759	                            <span>Nome Completo</span>
760	                        </label>
761	                        <input
762	                            type="text"
763	                            placeholder="Digite o nome completo"
764	                            {...register('nome')}
765	                            disabled={readonly}
766	                            className={getCedenteFormInputClass()}
767	                        />
