    data: PfCedenteFormValues,
    event?: React.BaseSyntheticEvent,
    intent: 'partial' | 'finalize' = 'partial',
) => {
    event?.stopPropagation();
    saveIntentRef.current = intent;

    let modifiedFormFields = buildCedenteCreateFormFields(
        data as unknown as Record<string, unknown>,
        dirtyFields,
        PF_PARTIAL_CREATE_REQUIRED_FIELDS,
    );

    // Garante que 'tipo' sempre seja incluído
    if (!modifiedFormFields.includes('tipo')) {
        modifiedFormFields = [...modifiedFormFields, 'tipo'];
    }

    // Garante que 'nacionalidade' sempre seja incluído quando preenchida
    if (data.nacionalidade && !modifiedFormFields.includes('nacionalidade')) {
        modifiedFormFields = [...modifiedFormFields, 'nacionalidade'];
    }

    if (data.telefone) {
        data.telefone = data.telefone.replace(/\D/g, ''); // remove tudo que não for dígito
    }

    if (data.data_nascimento) {
        data.data_nascimento = data.data_nascimento.split('/').reverse().join('-');
    }

    if (data.numero) {
        data.numero = String(data.numero);
    }

    if (mode === 'create' || mode === 'createFromPj') {
        await createCedente.mutateAsync({
            data,
            formFields: modifiedFormFields,
        });
        return;
    }

    if (mode === 'edit' && modifiedFormFields.length > 0) {
        await updateCedente.mutateAsync({
            data,
            formFields: modifiedFormFields,
        });
    } else if (mode === 'edit') {
        sendToastMessage({
            title: 'Atenção',
            description: 'É necessário ao menos modificar um campo para atualizar os dados.',
            type: 'warning',
        });
    }
};

function onFormFailure(formErrors: FieldErrors<PfCedenteFormValues>) {
    captureCedenteFormEvent('crm_broker_cedente_form_save_partial_failed', {
        form_tipo: 'PF',
        mode: mode === 'edit' ? 'edit' : 'create',
        reason: 'client_validation',
    });
    handleCedenteFormValidationFailure({
        errors: formErrors,
        formTipo: 'PF',
        mode: mode === 'edit' ? 'edit' : 'create',
        setFocus: (name) => setFocus(name as Parameters<typeof setFocus>[0]),
    });
}

function onSavePartial(data: PfCedenteFormValues, event?: React.BaseSyntheticEvent) {
    return onSubmit(data, event, 'partial');
}

async function onFinalizeClick() {
    const values = getValues();
    const isValid = applyCedenteFullSchemaValidation({
        schema: pfCedenteFormSchema,
        values,
        setError,
        clearErrors,
        formTipo: 'PF',
        mode: mode === 'edit' ? 'edit' : 'create',
        setFocus: (name) => setFocus(name as Parameters<typeof setFocus>[0]),
    });
    if (!isValid) return;
    await onSubmit(values, undefined, 'finalize');
}

useEffect(() => {
    hydratedRepresentanteIdRef.current = null;
}, [representanteLegalId]);

useEffect(() => {
    if (mode !== 'edit' || !representanteData) return;
    const incomingId = String(representanteData.id || representanteLegalId || '');
    if (!shouldHydrateCedenteForm(hydratedRepresentanteIdRef.current, incomingId)) return;

    setPixOption(
        validationSelectPix(
            representanteData.informacoes_bancarias?.pix || '',
        ) as unknown as PixOption,
    );
    const mapped = mapCedenteDataToFormValues(representanteData, 'pf');
    for (const [key, value] of Object.entries(mapped)) {
        setValue(key as keyof PfCedenteFormValues, value);
    }
    hydratedRepresentanteIdRef.current = incomingId;
}, [representanteData, mode, representanteLegalId, setValue]);

useEffect(() => {
    if (mode === 'create' && isFullPercentage && cessionPercentageAvailable > 0) {
        setValue('percentual_cessao', '100');
    }
}, [mode, isFullPercentage, cessionPercentageAvailable, setValue]);

useEffect(() => {
    if (
        mode !== 'create' ||
        isFromFormPj ||
        didPrefillFromOficioRef.current ||
        !extratoData ||
        !isLinkedCedentesLoaded
    ) {
        return;
    }

    const prefill = resolveOficioCedentePrefill({
        oficio: extratoData,
        hasLinkedCedente,
        formTipo: 'PF',
    });
    if (!prefill) return;

    didPrefillFromOficioRef.current = true;
    nameLockedFromOficioRef.current = true;
    setValue('nome', prefill.name, { shouldDirty: true });
    setValue('cpf', prefill.documentMasked, { shouldDirty: true });
    setOficioPrefillNotice(prefill.reviewNotice);
}, [
    mode,
    isFromFormPj,
    extratoData,
    hasLinkedCedente,
    isLinkedCedentesLoaded,
    setValue,
]);

useEffect(() => {
    if (mode === 'create' && pfData?.retorno) {
        const data = pfData.retorno;

        // Ofício name wins over bureau; keep asking the user to review.
        if (data.nome && !nameLockedFromOficioRef.current) {
            setValue('nome', data.nome, { shouldDirty: true });
        }
        if (data.nomeMae) setValue('nome_mae', data.nomeMae, { shouldDirty: true });
        if (data.dataNascimento) {
            // Converte de YYYY-MM-DD para DD/MM/YYYY
            const dataFormatada = data.dataNascimento.split(' ')[0];
            setValue('data_nascimento', dataFormatada, { shouldDirty: true });
        }

        const primeiroTelefone = data.telefones?.[0]?.telefoneComDDD;
        if (primeiroTelefone) setValue('telefone', primeiroTelefone, { shouldDirty: true });

        const primeiroEmail = data.emails?.[0]?.enderecoEmail;
        if (primeiroEmail) setValue('email', primeiroEmail, { shouldDirty: true });

        const endereco = data.enderecos?.[0];
        if (endereco) {
            if (endereco.cep) setValue('cep', endereco.cep, { shouldDirty: true });
            if (endereco.logradouro)
                setValue('logradouro', endereco.logradouro, { shouldDirty: true });
            if (endereco.numero) setValue('numero', endereco.numero, { shouldDirty: true });
            if (endereco.complemento)
                setValue('complemento', endereco.complemento, { shouldDirty: true });
            if (endereco.bairro) setValue('bairro', endereco.bairro, { shouldDirty: true });
            if (endereco.cidade) setValue('municipio', endereco.cidade, { shouldDirty: true });
            if (endereco.uf) setValue('estado', endereco.uf, { shouldDirty: true });
        }
    }
}, [pfData, mode, setValue]);

useEffect(() => {
    const handler = setTimeout(() => {
        setDebouncedCpf(currentCpf);
    }, 700);
    return () => clearTimeout(handler);
}, [currentCpf]);

useEffect(() => {
    setEnrichSuggestionDismissed(false);
}, [debouncedCpf]);

const watchedSoftForEnrich = watch([
    'rg',
    'data_nascimento',
    'estado_civil',
    'profissao',
    'nome_mae',
    'nome_pai',
