async function handleEnrichPfFromDirectData() {
    if (!currentCpf || isEnrichingPf) return;
    setIsEnrichingPf(true);
    try {
        const response = await getPFData(currentCpf);
        if (!response?.retorno) {
            sendToastMessage({
                title: 'Não encontramos dados para este CPF.',
                type: 'warning',
            });
            return;
        }

        const current = {
            ...pfEnrichFormValues,
            ...getValues(),
        };
        const fill = buildCedentePfEnrichFillIfEmpty(current, response.retorno);
        const filledKeys = Object.keys(fill);
        if (filledKeys.length === 0) {
            sendToastMessage({
                title: 'Nenhum campo vazio pôde ser preenchido com a consulta.',
