import {
    buildCedenteValidationFailureView,
    captureCedenteFormEvent,
    handleCedenteFormValidationFailure,
} from '@/functions/analytics/cedenteFormValidationUx';
import type { FieldErrors, FieldValues, UseFormClearErrors, UseFormSetError } from 'react-hook-form';
import type { z } from 'zod';

/**
 * Valida com schema full (Finalizar Cadastro), aplica setError e dispara UX/analytics.
 * @returns true se válido
 */
export function applyCedenteFullSchemaValidation<T extends FieldValues>(params: {
    schema: z.ZodTypeAny;
    values: unknown;
    setError: UseFormSetError<T>;
    clearErrors: UseFormClearErrors<T>;
    formTipo: 'PF' | 'PJ';
    mode?: 'create' | 'edit';
    setFocus?: (name: string) => void;
    onBeforeScroll?: (firstPath: string) => void;
}): boolean {
    const {
        schema,
        values,
        setError,
        clearErrors,
        formTipo,
        mode = 'create',
        setFocus,
        onBeforeScroll,
    } = params;

    const result = schema.safeParse(values);
    if (result.success) {
        clearErrors();
        return true;
    }

    clearErrors();
    const fieldErrors = {} as FieldErrors<T>;

    for (const issue of result.error.issues) {
        const path = String(issue.path[0] ?? '');
        if (!path) continue;
        const key = path as keyof T & string;
        if (!fieldErrors[key]) {
            const error = { type: 'manual' as const, message: issue.message };
            fieldErrors[key] = error as FieldErrors<T>[typeof key];
            setError(key as Parameters<UseFormSetError<T>>[0], error);
        }
    }

    const view = buildCedenteValidationFailureView(fieldErrors);
    captureCedenteFormEvent('crm_broker_cedente_form_finalize_validation_failed', {
        form_tipo: formTipo,
        mode,
        invalid_count: view.invalidCount,
        invalid_field_paths: view.paths,
        invalid_field_labels: view.invalidFieldLabels,
    });

    handleCedenteFormValidationFailure({
        errors: fieldErrors,
        formTipo,
        mode,
        setFocus,
        onBeforeScroll,
    });

    return false;
}

