async function onSubmit(data: CedenteFormValues) {
    saveIntentRef.current = 'partial';
    await persistCedente(data);
}

function onFinalizeClick() {
    saveIntentRef.current = 'finalize';
    const values = getValues();
    const isValid = applyCedenteFullSchemaValidation({
        schema: type === 'pf' ? pfCedenteFormSchema : pjCedenteFormSchema,
        values,
        setError,
        clearErrors,
        formTipo: type === 'pj' ? 'PJ' : 'PF',
        mode: 'edit',
        setFocus: (name) => setFocus(name as Parameters<typeof setFocus>[0]),
        onBeforeScroll: openAccordionForPath,
    });
    if (!isValid) return;
    void persistCedente(values);
}

function onFormFailure(formErrors: FieldErrors<CedenteFormValues>) {
    handleCedenteFormValidationFailure({
        errors: formErrors,
        formTipo: type === 'pj' ? 'PJ' : 'PF',
        mode: 'edit',
        setFocus: (name) => setFocus(name as Parameters<typeof setFocus>[0]),
        onBeforeScroll: openAccordionForPath,
    });
}

const updateCedente = useMutation({
    mutationFn: async (paramObj: { data: CedenteFormValues; formFields: string[] }) => {
        const { data, formFields } = paramObj;
        await updateCedenteInfo(
            data as unknown as FormValuesForBrokerCedente,
            formFields,
            cedenteInfo?.id as string,
        );
    },
    onMutate: async () => {
        setIsUpdating(true);
    },
    onError: (error) => {
        if (error instanceof AxiosError) {
            sendToastMessage({
                title: error.response?.data.detail || 'Erro ao atualizar cedente',
                type: 'error',
            });
        }
    },
    onSuccess: async () => {
        const isPartial = saveIntentRef.current === 'partial';
        captureCedenteFormEvent(
            isPartial
                ? 'crm_broker_cedente_form_save_partial_succeeded'
                : 'crm_broker_cedente_form_finalize_succeeded',
            {
                form_tipo: type === 'pj' ? 'PJ' : 'PF',
                mode: 'edit',
            },
        );
        sendToastMessage({
            title: isPartial
                ? 'Dados salvos. Você pode continuar preenchendo.'
                : 'Cadastro finalizado.',
            type: 'success',
        });

        queryClient.invalidateQueries({ queryKey: [QueryKeys.cedentes.data, cedenteInfo?.id] });
        await reverificarExigenciasProposta(queryClient, vigenteProposalData?.uuid);
        queryClient.invalidateQueries({
            queryKey: [QueryKeys.cedentes.linkedExtratoCedentes, extratoId],
        });
        queryClient.invalidateQueries({
            queryKey: [QueryKeys.oficios.item, extratoId],
        });
        queryClient.invalidateQueries({
            queryKey: [QueryKeys.cedentes.linkedEsteirasCedente],
        });
        reset(undefined, { keepValues: true });
        setIsUpdating(false);
    },
});

const handleUnlinkCedente = () => {
    if (!cedenteInfo?.relation_id || !extratoId) return;
    unlinkCedenteMutation.mutate(cedenteInfo.relation_id);
};

// função para desvicular o representante legal
const handleUnlinkRepresentante = async () => {
    setIsUnlinkingRepresentante(true);
    let updatingCedenteToastId: string | number | undefined;
    try {
        await unlinkRepresentanteFromCedente(cedenteInfo?.id as string);
        sendToastMessage({ title: 'Representante desvinculado.', type: 'success' });

        await sleep(1);
        updatingCedenteToastId = sendToastMessage({
            title: 'Atualizando dados do cedente...',
            type: 'loading',
        });
        await queryClient.invalidateQueries({
            queryKey: [QueryKeys.cedentes.data, cedenteInfo?.id],
        });

        sendToastMessage({
            title: 'Dados do cedente atualizados.',
            type: 'success',
            previousToastId: updatingCedenteToastId,
        });
        await reverificarExigenciasProposta(queryClient, vigenteProposalData?.uuid);
    } catch (error) {
        if (error instanceof AxiosError) {
            sendToastMessage({
                title: error.response?.data.detail || 'Erro ao desvincular representante',
                type: 'error',
                previousToastId: updatingCedenteToastId,
            });
        }
    } finally {
        setIsUnlinkingRepresentante(false);
    }
};

// função para definir o ID do representante legal e abrir o modal de edição
const handleEditRepresentante = () => {
    if (cedenteData?.representante_legal?.id) {
        setRepresentanteLegalId(cedenteData.representante_legal.id);
    }
};

const searchCep = async (cep: string) => {
    const digits = cep.replace(/\D/g, '');

    if (digits.length !== 8) return;
    if (lastCepLookupDigitsRef.current === digits && isSearchingCep) return;

    try {
        setIsSearchingCep(true);
        const result = await fetchAddressByCep(digits);
        lastCepLookupDigitsRef.current = digits;
        setValue('municipio', result.city, { shouldDirty: true });
        setValue('estado', result.state, { shouldDirty: true });
        setValue('bairro', result.neighborhood, { shouldDirty: true });
        setValue('logradouro', result.street, { shouldDirty: true });
    } catch {
        sendToastMessage({
            title: 'Erro ao buscar CEP',
            description: 'Não foi possível buscar os dados do CEP informado.',
            type: 'error',
        });
    } finally {
        setIsSearchingCep(false);
    }
};

